package com.autoops.auth.service;import com.autoops.auth.dto.AuthDtos;import com.autoops.auth.entity.RefreshToken;import com.autoops.auth.repository.RefreshTokenRepository;import com.autoops.user.entity.User;import com.autoops.user.repository.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Instant;import java.util.*;@Service public class AuthService{private final AuthenticationManager auth;private final UserRepository users;private final JwtService jwt;private final RefreshTokenRepository refresh;private final long refreshMs;public AuthService(AuthenticationManager a,UserRepository u,JwtService j,RefreshTokenRepository r,@Value("${autoops.jwt.refresh-expiration}")long ms){auth=a;users=u;jwt=j;refresh=r;refreshMs=ms;}@Transactional public Session login(AuthDtos.LoginRequest r){Authentication x=auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));User u=users.findByUsername(x.getName()).orElseThrow();return issue(u);}@Transactional public Session refresh(String raw){String hash=hash(raw);RefreshToken t=refresh.findByTokenHash(hash).orElseThrow(()->new BadCredentialsException("Invalid refresh token"));if(t.getRevokedAt()!=null||t.getExpiresAt().isBefore(Instant.now()))throw new BadCredentialsException("Refresh token expired");User u=users.findById(t.getUserId()).orElseThrow();if(u.getStatus()!=User.Status.ACTIVE)throw new BadCredentialsException("User disabled");t.setRevokedAt(Instant.now());refresh.save(t);return issue(u);}@Transactional public void logout(String raw){if(raw==null)return;refresh.findByTokenHash(hash(raw)).ifPresent(t->{t.setRevokedAt(Instant.now());refresh.save(t);});}private Session issue(User u){String raw=UUID.randomUUID()+"."+UUID.randomUUID();RefreshToken t=new RefreshToken();t.setUserId(u.getId());t.setTokenHash(hash(raw));t.setExpiresAt(Instant.now().plusMillis(refreshMs));refresh.save(t);return new Session(new AuthDtos.AuthResponse(jwt.create(u.getId(),u.getRole().name()),900),raw); }private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Session(AuthDtos.AuthResponse response,String refreshToken){}}
